package com.sakti.banking.controller; import com.sakti.banking.dto.BeneficiaryRequest; import com.sakti.banking.entity.Beneficiary; import com.sakti.banking.service.BeneficiaryService; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/beneficiaries") public class BeneficiaryController {private final BeneficiaryService svc;public BeneficiaryController(BeneficiaryService s){svc=s;} @PostMapping public Beneficiary add(Authentication a,@Valid @RequestBody BeneficiaryRequest r){return svc.add(a.getName(),r);} @GetMapping public List<Beneficiary> mine(Authentication a){return svc.mine(a.getName());}}
